// Read-only access to the content generated by scripts/content.mjs.
// index.json (metadata only) is bundled; each article body is a lazily loaded chunk.
import index from "@/generated/index.json";
import site from "@/site.config.json";

export const SITE = site;

export type PostMeta = {
  slug: string;
  title: string;
  date: string;
  updated: string | null;
  description: string;
  category: string;
  platform: string | null;
  difficulty: string | null;
  tags: string[];
  featured: boolean;
  cover: string | null;
  readingTime: number;
};

export type Post = PostMeta & {
  html: string;
  toc: { depth: number; id: string; text: string }[];
  prev: { slug: string; title: string } | null;
  next: { slug: string; title: string } | null;
  related: string[];
};

export const PAGE_SIZE = 10;

export const CATEGORIES: Record<string, { label: string; blurb: string }> = {
  writeup: {
    label: "Writeups",
    blurb: "Lab and machine walkthroughs from HTB, TryHackMe and OffSec.",
  },
  research: {
    label: "Research",
    blurb: "Deeper dives into vulnerabilities, techniques and defences.",
  },
  tutorial: { label: "Tutorials", blurb: "Step-by-step guides to tools and techniques." },
  project: { label: "Projects", blurb: "Things I have built, and what I learned building them." },
  notes: { label: "Notes", blurb: "Checklists, methodology and short technical notes." },
};

const TAG_LABELS: Record<string, string> = {
  htb: "HTB",
  thm: "TryHackMe",
  offsec: "OffSec",
  jwt: "JWT",
  "sql-injection": "SQL injection",
};

export const PLATFORM_TAGS = ["htb", "thm", "offsec"];

export function tagLabel(tag: string) {
  return TAG_LABELS[tag] ?? tag.replace(/-/g, " ");
}

export function categoryLabel(cat: string) {
  return CATEGORIES[cat]?.label ?? cat;
}

export const posts = index as PostMeta[];

export const postsBySlug = new Map(posts.map((p) => [p.slug, p]));

export function countBy(values: string[]) {
  const m = new Map<string, number>();
  for (const v of values) m.set(v, (m.get(v) ?? 0) + 1);
  return [...m.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
}

export const allTags = () => countBy(posts.flatMap((p) => p.tags));
export const allCategories = () => countBy(posts.map((p) => p.category));

const bodies = import.meta.glob<Post>("../generated/posts/*.json", { import: "default" });

export async function getPost(slug: string): Promise<Post | null> {
  const load = bodies[`../generated/posts/${slug}.json`];
  return load ? await load() : null;
}

export function formatDate(iso: string) {
  return new Date(iso + "T00:00:00Z").toLocaleDateString("en-GB", {
    day: "numeric",
    month: "short",
    year: "numeric",
    timeZone: "UTC",
  });
}

/** Absolute URL with the trailing slash GitHub Pages serves directories with. */
export function absUrl(path: string) {
  return SITE.url + (path === "/" ? "/" : path.replace(/\/?$/, "/"));
}

export function pageHead(opts: {
  title: string;
  description: string;
  path: string;
  type?: string;
  noindex?: boolean;
}) {
  const title = opts.title === SITE.title ? SITE.title : `${opts.title} · ${SITE.title}`;
  const url = absUrl(opts.path);
  return {
    meta: [
      { title },
      { name: "description", content: opts.description },
      { property: "og:title", content: title },
      { property: "og:description", content: opts.description },
      { property: "og:type", content: opts.type ?? "website" },
      { property: "og:url", content: url },
      { name: "twitter:card", content: "summary" },
      { name: "twitter:title", content: title },
      { name: "twitter:description", content: opts.description },
      ...(opts.noindex ? [{ name: "robots", content: "noindex" }] : []),
    ],
    links: opts.noindex ? [] : [{ rel: "canonical", href: url }],
  };
}
